// Normaliza y recorta la entrada antes de tocar la base.
// La validación de negocio de verdad vive en crear_reserva(); esto
// solo evita basura y bots obvios.
const b = $input.first().json.body || {};

// Honeypot: campo oculto en el formulario. Si viene lleno, es un bot.
const esBot = (b.apellido2 || '').toString().trim() !== '';

const txt = (v, max) => (v == null ? '' : v.toString().trim().slice(0, max));

return [{ json: {
  es_bot:      esBot,
  slug:        txt(b.slug, 60) || 'tumbao',
  sesion_id:   parseInt(b.sesion_id, 10) || 0,
  first_name:  txt(b.first_name, 80),
  last_name:   txt(b.last_name, 80),
  phone:       txt(b.phone, 25),
  email:       txt(b.email, 120),
  habeas_data: b.habeas_data === true || b.habeas_data === 'true'
} }];

// Al bot le devolvemos un 200 vacío: nunca toca la base y no
// aprende nada del error.
return [{ json: {
  http_status: 200, ok: true, error: null, mensaje: '', codigo: 'OK'
} }];

// Arma el texto de confirmación y la respuesta para la página.
const r = $input.first().json.r;

const fecha = new Intl.DateTimeFormat('es-CO', {
  timeZone: 'America/Bogota', weekday: 'long', day: 'numeric', month: 'long'
}).format(new Date(r.start_at));
const hora = new Intl.DateTimeFormat('es-CO', {
  timeZone: 'America/Bogota', hour: 'numeric', minute: '2-digit', hour12: true
}).format(new Date(r.start_at))
  .replace(/\u202f|\u00a0/g, ' ')
  .replace(/\s*a\.\s*m\./i, ' am')
  .replace(/\s*p\.\s*m\./i, ' pm');

const mensaje =
  `¡Listo ${r.nombre}! 💃\n\n` +
  `Tu cupo en *${r.clase}* quedó reservado para el ${fecha} a las ${hora}.\n\n` +
  `Tu código: *${r.codigo}*\n` +
  `Muéstralo en recepción cuando llegues.\n\n` +
  `Llega 10 minutos antes. ¡Nos vemos! 🔥`;

return [{ json: {
  ok: true,
  codigo: r.codigo,
  clase: r.clase,
  fecha,
  hora,
  ya_existia: r.ya_existia,
  mensaje_cliente: mensaje,
  telefono_e164: '57' + r.telefono
} }];

// Traduce el error de negocio a un código HTTP.
const r = $input.first().json.r || {};

const mapa = {
  habeas_data_requerido:  400,
  nombre_invalido:        400,
  telefono_invalido:      400,
  academia_no_encontrada: 404,
  sesion_no_encontrada:   404,
  sesion_cancelada:       409,
  sesion_ya_empezo:       409,
  sin_cupo:               409
};

return [{ json: {
  http_status: mapa[r.error] || 400,
  ok: false,
  error: r.error || 'desconocido',
  codigo: null,
  mensaje: r.mensaje || 'No pudimos completar la reserva. Escríbenos por WhatsApp.'
} }];
